#include <iostream>
#include <vector>
#include <list>
#include <algorithm>

template <typename Container>
void print_elements(const Container& c, const std::string& label) {
    std::cout << label;
    for (const auto& elem : c) {
        std::cout << elem << ' ';
    }
    std::cout << '\n';
}

int main() {
    std::vector<int> coll = {1, 2, 3, 4, 5};
    std::list<int> coll2 = {10, 20, 30};

    // Copy elements from coll to coll2, inserting after the first element
    std::copy(
        coll.begin(),
        coll.end(),
        std::inserter(coll2, std::next(coll2.begin()))
    );

    print_elements(coll2, "list: ");
    return 0;
}
